<?php
require_once 'config/database.php';require_once 'includes/auth.php';require_once 'includes/functions.php';require_login();$uid=current_user()['user_id'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$rid=(int)$_POST['request_id'];$s=$pdo->prepare("SELECT * FROM SkillRequests WHERE request_id=? AND (sender_id=? OR receiver_id=?) AND status='accepted'");$s->execute([$rid,$uid,$uid]);$r=$s->fetch();if(!$r){flash('error','Only accepted requests can create sessions.');}else{$teacher=$r['receiver_id'];$learner=$r['sender_id'];$skill=$r['requested_skill_id'];$p=[$rid,$teacher,$learner,$skill,trim($_POST['session_title']),trim($_POST['session_description']),$_POST['session_date'],$_POST['start_time'],$_POST['end_time'],$_POST['session_mode'],trim($_POST['meeting_link']),trim($_POST['location'])];$q=$pdo->prepare("INSERT INTO LearningSessions(request_id,teacher_id,learner_id,skill_id,session_title,session_description,session_date,start_time,end_time,session_mode,meeting_link,location) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)");$q->execute($p);flash('success','Session scheduled.');redirect('sessions.php');}}
$req=$pdo->prepare("SELECT r.request_id,r.sender_id,r.receiver_id,rs.skill_name FROM SkillRequests r JOIN Skills rs ON rs.skill_id=r.requested_skill_id WHERE r.status='accepted' AND (r.sender_id=? OR r.receiver_id=?)");$req->execute([$uid,$uid]);$req=$req->fetchAll();$title='Schedule session';include 'includes/header.php';
?>
<div class="auth-wrap"><form method="post" class="auth-card form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="eyebrow">BOOK A SWAP</div><h1>Schedule a session.</h1><label>Accepted request<select name="request_id" required><?php foreach($req as $r):?><option value="<?=$r['request_id']?>">#<?=$r['request_id']?> · <?=e($r['skill_name'])?></option><?php endforeach;?></select></label><label>Title<input name="session_title" required></label><label>Description<textarea name="session_description"></textarea></label><div class="form-grid"><label>Date<input type="date" name="session_date" required></label><label>Mode<select name="session_mode"><option value="online">Online</option><option value="offline">Offline</option></select></label></div><div class="form-grid"><label>Start<input type="time" name="start_time" required></label><label>End<input type="time" name="end_time" required></label></div><label>Meeting link<input name="meeting_link"></label><label>Location<input name="location"></label><button class="btn">Schedule session →</button></form></div>
<?php include 'includes/footer.php'; ?>
